class Solution:

	def check(self, N, M, Edges):
		adj = [[] for _ in range(N + 1)]
		for i in range(M):
			adj[Edges[i][0]].append(Edges[i][1])
			adj[Edges[i][1]].append(Edges[i][0])
		visit = [0] * (N + 1)
		ans = [False] * 1

		def fun(i, c):
			if c == N - 1:
				ans[0] = True
				return
			if ans[0] == True:
				return
			visit[i] = 1
			for j in adj[i]:
				if visit[j] == 0:
					fun(j, c + 1)
			visit[i] = 0
		for i in range(1, N + 1):
			fun(i, 0)
			if ans[0] == True:
				return True
		return False
